'use strict';

// MODULES //

var tape = require( 'tape' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var Axis = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Axis, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor', function test( t ) {
	var axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	t.strictEqual( instanceOf( axis, Axis ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword', function test( t ) {
	var axis;
	var ctor;

	ctor = Axis;
	axis = ctor({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	t.strictEqual( instanceOf( axis, Axis ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var axis;
	var ctor;

	ctor = Axis;
	axis = ctor({
		'scale': 'xScale',
		'orient': 'bottom',
		'grid': true
	});
	t.strictEqual( instanceOf( axis, Axis ), true, 'returns expected value' );
	t.strictEqual( axis.grid, true, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var axis = new Axis( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the constructor throws an error if not provided a `scale` option', function test( t ) {
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		var axis = new Axis({ // eslint-disable-line no-unused-vars
			'orient': 'bottom'
		});
	}
});

tape( 'the constructor throws an error if not provided an `orient` option', function test( t ) {
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		var axis = new Axis({ // eslint-disable-line no-unused-vars
			'scale': 'xScale'
		});
	}
});

tape( 'the constructor has a read-only `name` property', function test( t ) {
	t.strictEqual( Axis.name, 'Axis', 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON', function test( t ) {
	var expected;
	var axis;
	var json;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	json = axis.toJSON();

	expected = {
		'aria': true,
		'description': '',
		'domain': true,
		'domainCap': 'butt',
		'domainDash': [],
		'domainOpacity': 1,
		'grid': false,
		'gridCap': 'butt',
		'gridDash': [],
		'gridOpacity': 1,
		'labelBound': false,
		'labelFlushOffset': 0,
		'labelOpacity': 1,
		'labelOverlap': false,
		'labels': true,
		'labelSeparation': 0,
		'orient': 'bottom',
		'position': 0,
		'scale': 'xScale',
		'tickCap': 'butt',
		'tickDash': [],
		'tickOpacity': 1,
		'ticks': true,
		'title': [ '' ],
		'titleAnchor': null,
		'titleOpacity': 1,
		'translate': 0.5,
		'zindex': 0
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

