tape( 'the `toJSON` method is implicitly invoked by `JSON.stringify`', function test( t ) {
	var expected;
	var axis;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});

	expected = {
		'aria': true,
		'description': '',
		'domain': true,
		'domainCap': 'butt',
		'domainDash': [],
		'domainOpacity': 1,
		'grid': false,
		'gridCap': 'butt',
		'gridDash': [],
		'gridOpacity': 1,
		'labelBound': false,
		'labelFlushOffset': 0,
		'labelOpacity': 1,
		'labelOverlap': false,
		'labels': true,
		'labelSeparation': 0,
		'orient': 'bottom',
		'position': 0,
		'scale': 'xScale',
		'tickCap': 'butt',
		'tickDash': [],
		'tickOpacity': 1,
		'ticks': true,
		'title': [ '' ],
		'titleAnchor': null,
		'titleOpacity': 1,
		'translate': 0.5,
		'zindex': 0
	};
	t.strictEqual( JSON.stringify( axis ), JSON.stringify( expected ), 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance which inherits from EventEmitter', function test( t ) {
	var axis;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});

	t.strictEqual( typeof axis.on, 'function', 'returns expected value' );
	t.strictEqual( typeof axis.emit, 'function', 'returns expected value' );
	t.strictEqual( typeof axis.removeListener, 'function', 'returns expected value' );

	t.end();
});

tape( 'the constructor ignores unrecognized options', function test( t ) {
	var axis;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom',
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( axis.scale, 'xScale', 'returns expected value' );
	t.strictEqual( hasOwnProp( axis, 'beep' ), false, 'returns expected value' );
	t.strictEqual( hasOwnProp( axis, 'foo' ), false, 'returns expected value' );

	t.end();
});
